  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Altdorf – Telldenkmal', 'Hlavní město kantonu Uri s legendárním pomníkem Viléma Tella na náměstí — právě tady měl podle pověsti sestřelit jablko z hlavy svého syna. Ideální místo na kávu před stoupáním na Klausen.', 46.8805, 8.6440, 'https://commons.wikimedia.org/wiki/Special:FilePath/Telldenkmal%20Altdorf.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Telldenkmal%20Altdorf.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Telldenkmal%20Altdorf%2001%2011.jpg"}'::text[], 0),
    (v_route, 'Klausenpass', 'Průsmyk ve výšce 1 948 m s jedním z nejplynulejších stoupání v Alpách — široké zatáčky, dobrý asfalt a výhledy na štíty Glarnských Alp. Na vrcholu stojí horský hotel s terasou přímo u silnice.', 46.8676, 8.8558, 'https://commons.wikimedia.org/wiki/Special:FilePath/Klausenpass%2C%20Uri%2C%20Switzerland.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Klausenpass%2C%20Uri%2C%20Switzerland.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Uri-Glarus%20Klausenpass%2009.JPG"}'::text[], 1),
    (v_route, 'Urnerboden', 'Největší alpská pastvina Švýcarska — kilometry dlouhá náhorní louka mezi skalními stěnami, po které se silnice line jako podle pravítka. V létě tu žije přes tisíc krav a čas tu plyne pomaleji.', 46.8890, 8.9130, 'https://commons.wikimedia.org/wiki/Special:FilePath/Urnerboden2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Urnerboden2.jpg"}'::text[], 2),
    (v_route, 'Glarus', 'Kantonální metropole sevřená horami, známá tím, že o zákonech tu dodnes hlasují občané zvednutím ruky na náměstí. Hezká zastávka na doplnění paliva i energie před Pragelem.', 47.0404, 9.0679, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glarus%20Panorama.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Glarus%20Panorama.jpg"}'::text[], 3),
    (v_route, 'Klöntalersee', 'Tyrkysové jezero v hlubokém údolí pod stěnou Glärnische — jedno z nejfotogeničtějších míst kantonu Glarus. Silnice vede přímo po břehu a láká k zastávce na koupání či piknik.', 47.0244, 8.9760, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%B6ntalersee%20in%20der%20Gemeinde%20Glarus%2C%20Kanton%20Glarus%20-%2019309679699.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kl%C3%B6ntalersee%20in%20der%20Gemeinde%20Glarus%2C%20Kanton%20Glarus%20-%2019309679699.jpg"}'::text[], 4),
    (v_route, 'Pragelpass', 'Úzký, divoký průsmyk (1 550 m) mezi Klöntalem a Muotathalem — jednoproudá silnička, výhybny a naprosté ticho. O víkendech je glarská strana pro motorová vozidla uzavřena, ve všední den je to ale motorkářský klenot.', 46.9770, 8.8930, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pragelpass.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pragelpass.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pragel03.jpg"}'::text[], 5),
    (v_route, 'Schwyz – Hauptplatz', 'Městečko, které dalo Švýcarsku jméno. Barokní náměstí s radnicí zdobenou freskami z bitvy u Morgartenu je důstojná tečka za okruhem — kavárny s výhledem na štíty Mythen.', 47.0207, 8.6530, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schwyz%20Hauptplatz%20mit%20Rathaus.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schwyz%20Hauptplatz%20mit%20Rathaus.JPG"}'::text[], 6);
